/* Class of Champions: add-on banner, latar, suara pengumuman, dan efek benar/salah.
   Pasang: tambahkan <script src="champions-ui.js"></script> tepat sebelum </body> pada file HTML utama. */
(()=>{
const IMG={"landing": {"src": "data:image/jpeg;base64,", "w": 1600, "h": 586}, "b1": {"src": "data:image/jpeg;base64,", "w": 675, "h": 262}, "b2": {"src": "data:image/jpeg;base64,", "w": 674, "h": 255}, "b3": {"src": "data:image/jpeg;base64,", "w": 663, "h": 262}};
/* ===== TEKS SUARA PENGUMUMAN (boleh diubah) ===== */
const VOICE={landing:'Selamat datang di Class of Champions! Siapkan dirimu untuk petualangan pecahan, persen, dan desimal.'};

const st=document.createElement('style');
st.textContent=`#bgimg{position:fixed;inset:0;z-index:-1;background:center/cover no-repeat;filter:blur(9px) brightness(.42) saturate(1.2);transform:scale(1.12);pointer-events:none;transition:opacity .4s}
.hero{position:relative;width:100%;max-width:780px;margin:12px auto;border-radius:16px;border:2px solid var(--cy);background:#000 center/100% 100% no-repeat;filter:none;backdrop-filter:none;box-shadow:0 0 34px #35e0ff66}
.hero button{position:absolute;right:10px;bottom:10px;padding:.35em .7em}`;
document.head.appendChild(st);
const bg=document.createElement('div');bg.id='bgimg';document.body.prepend(bg);

let ctx,cur=null,unlocked=false,pending=null;
const on=()=>{try{return S.snd}catch(e){return 1}};
function C(){ctx=ctx||new(window.AudioContext||window.webkitAudioContext)();if(ctx.state==='suspended')ctx.resume();return ctx}
function nt(f,t0,d,type='sawtooth',v=.16,lp=2400,f2){if(!on())return;try{const c=C(),t=c.currentTime+t0,o=c.createOscillator(),g=c.createGain(),fl=c.createBiquadFilter();
 o.type=type;o.frequency.setValueAtTime(f,t);if(f2)o.frequency.exponentialRampToValueAtTime(f2,t+d);
 fl.type='lowpass';fl.frequency.setValueAtTime(lp*.35,t);fl.frequency.exponentialRampToValueAtTime(lp,t+Math.min(.1,d));
 g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(v,t+.03);g.gain.exponentialRampToValueAtTime(.0001,t+d);
 o.connect(fl);fl.connect(g);g.connect(c.destination);o.start(t);o.stop(t+d+.05)}catch(e){}}
const kick=(t0,v=.6)=>nt(160,t0,.35,'sine',v,3000,38);
function crash(t0,d=1.4,v=.16){if(!on())return;try{const c=C(),t=c.currentTime+t0,n=Math.floor(c.sampleRate*d),b=c.createBuffer(1,n,c.sampleRate),x=b.getChannelData(0);for(let i=0;i<n;i++)x[i]=Math.random()*2-1;
 const s=c.createBufferSource(),h=c.createBiquadFilter(),g=c.createGain();s.buffer=b;h.type='highpass';h.frequency.value=5500;g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(.001,t+d);s.connect(h);h.connect(g);g.connect(c.destination);s.start(t)}catch(e){}}
const sfx={
 welcome(){kick(0);nt(131,0,.9,'sawtooth',.14,900);[392,523,659,784].forEach((f,i)=>nt(f,.25+i*.17,.28,'sawtooth',.15));
  kick(.9);kick(1.05,.5);[523,659,784,1047].forEach(f=>nt(f,1.2,1.6,'sawtooth',.11,3200));nt(131,1.2,1.6,'sawtooth',.16,900);
  crash(1.2);[2093,2637,3136].forEach((f,i)=>nt(f,1.35+i*.12,1,'sine',.05))},
 stinger(){kick(0);nt(98,0,.6,'sawtooth',.14,800);[392,523,784].forEach((f,i)=>nt(f,.05+i*.12,.35,'sawtooth',.14));crash(.3,.8,.08)},
 ok(){[659,784,988,1319].forEach((f,i)=>nt(f,i*.08,.22,'triangle',.2,4000));[1047,1319,1568].forEach(f=>nt(f,.34,.9,'sawtooth',.08,3500));nt(2637,.4,.8,'sine',.06);crash(.34,.7,.06)},
 no(){nt(311,0,.4,'sawtooth',.2,1400,277);nt(247,.4,.7,'sawtooth',.2,1000,155);nt(98,0,1,'square',.07,400)}};

/* ===== FILE AUDIO =====
   Semua file berada di folder yang sama dengan file HTML. Kosongkan ('') untuk memakai suara bawaan.
   Jika file tidak ditemukan, otomatis memakai suara bawaan (tidak error). */
const AUDIO={landing:'selamatdatang.mp3',ok:'benar.mp3',no:'salah.mp3',music:'musik.mp3'};
const MUSIC_VOL=.22; /* volume musik latar: 0 sampai 1 */
const cache={};let bgm=null,duckT;
function playFile(key,fb){const src=AUDIO[key];if(!src||!on())return fb&&fb();
 let used=false;const f=()=>{if(!used){used=true;AUDIO[key]='';fb&&fb()}};
 const a=cache[key]||(cache[key]=new Audio(src));a.onerror=f;try{a.currentTime=0}catch(e){}
 const p=a.play();if(p&&p.catch)p.catch(e=>{if(e&&e.name!=='NotAllowedError')f()})}
function startBGM(){if(!on()||!AUDIO.music)return;
 if(!bgm){bgm=new Audio(AUDIO.music);bgm.loop=true;bgm.volume=MUSIC_VOL;bgm.onerror=()=>{AUDIO.music='';bgm=null}}
 if(bgm.paused){const p=bgm.play();if(p&&p.catch)p.catch(()=>{})}}
function duck(ms){if(!bgm)return;bgm.volume=MUSIC_VOL*.3;clearTimeout(duckT);duckT=setTimeout(()=>{if(bgm)bgm.volume=MUSIC_VOL},ms)}

/* ganti bunyi benar/salah bawaan tanpa mengubah file utama */
const _tone=window.tone,OK=[523,659,784,1047,1319];
window.tone=function(f,t0,d,type,v){
 if(OK.includes(f)&&(type===undefined||type==='triangle')){if(f===523){playFile('ok',sfx.ok);duck(2200)}return}
 if((f===220||f===165)&&type==='sawtooth'){if(f===220){playFile('no',sfx.no);duck(2200)}return}
 return _tone.apply(this,arguments)};

try{speechSynthesis.getVoices()}catch(e){}
function say(t){if(!on()||!('speechSynthesis' in window))return;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t),vs=speechSynthesis.getVoices(),
 v=vs.find(x=>/^id([-_]|$)/i.test(x.lang))||vs.find(x=>/indones/i.test(x.name));if(v)u.voice=v;u.lang='id-ID';u.rate=.92;u.pitch=.8;speechSynthesis.speak(u)}catch(e){}}
function run(key){if(!key)return;
 if(key!=='landing'){startBGM();return}
 try{speechSynthesis.cancel()}catch(e){}
 playFile('landing',()=>{sfx.welcome();setTimeout(()=>{if(cur===key)say(VOICE.landing)},1400)});
 const w=cache.landing;if(w&&AUDIO.landing)w.onended=startBGM;
 setTimeout(startBGM,4000)}
function announce(key){if(!key)return;unlocked?run(key):pending=key}
['pointerdown','keydown'].forEach(ev=>addEventListener(ev,e=>{if(unlocked)return;unlocked=true;
 if(pending&&pending===cur&&!(e.target.closest&&e.target.closest('[data-a="mlogin"]')))run(pending);pending=null},true));
A.voice=()=>{unlocked=true;try{if(!S.snd){S.snd=1;save()}}catch(e){}run(cur)};

function decorate(){
 const a=document.getElementById('app');if(!a)return;
 if(bgm){if(!on())bgm.pause();else if(unlocked)startBGM()}
 const key=!sess?'landing':(['b1','b2','b3'].includes(ui.tab)?ui.tab:null);
 if(key!==cur){cur=key;announce(key)}
 bg.style.backgroundImage=key?`url(${IMG[key].src})`:'none';bg.style.opacity=key?1:0;
 if(!key){a.querySelectorAll('.hero').forEach(x=>x.remove());return}
 if(a.querySelector('.hero'))return;
 const i=IMG[key],h=document.createElement('div');h.className='hero';h.setAttribute('role','img');
 h.setAttribute('aria-label',{landing:'Clash of Champions',b1:'Choose Your Level',b2:'Clash of Calculation',b3:'The Grand Champion'}[key]);
 h.style.backgroundImage=`url(${i.src})`;h.style.aspectRatio=i.w+'/'+i.h;h.style.maxWidth=Math.min(780,i.w)+'px';/* jangan diperbesar melebihi ukuran asli agar tetap tajam */
 if(key==='landing')h.innerHTML='<button class="cyan" data-a="voice" aria-label="Putar sambutan">🔊 Putar sambutan</button>';
 if(key==='landing')a.querySelector('header.top')?.after(h);else a.querySelector('.panel')?.before(h)}
new MutationObserver(decorate).observe(document.getElementById('app'),{childList:true});
decorate();
})();
